/*!40101 SET NAMES utf8 */;

/*!40101 SET SQL_MODE=''*/;

/*!40014 SET @OLD_UNIQUE_CHECKS=@@UNIQUE_CHECKS, UNIQUE_CHECKS=0 */;
/*!40014 SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0 */;
/*!40101 SET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO' */;
/*!40111 SET @OLD_SQL_NOTES=@@SQL_NOTES, SQL_NOTES=0 */;
CREATE DATABASE /*!32312 IF NOT EXISTS*/`deic` /*!40100 DEFAULT CHARACTER SET latin1 */;

USE `deic`;

/*Table structure for table `account` */

DROP TABLE IF EXISTS `account`;

CREATE TABLE `account` (
  `username` varchar(100) NOT NULL,
  `pswd` varchar(20) DEFAULT NULL,
  `role` int(11) DEFAULT NULL COMMENT '1,表示超级管理员,具有管理所有权限.\n2,表示普通的管理员,不能管理其他用户.',
  PRIMARY KEY (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='后台信息表';

/*Data for the table `account` */

insert  into `account`(`username`,`pswd`,`role`) values ('admin','admin',1),('test1','123345',1);

/*Table structure for table `article` */

DROP TABLE IF EXISTS `article`;

CREATE TABLE `article` (
  `articleId` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) DEFAULT NULL COMMENT '文章标题',
  `content` longtext COMMENT '文章文本内容',
  `imgPath` varchar(200) DEFAULT NULL COMMENT '图片路径',
  `otherPackagePath` varchar(200) DEFAULT NULL COMMENT '附件存放的地址',
  `saveTime` datetime DEFAULT NULL COMMENT '文章保存时间,同ArticleList中的时间',
  PRIMARY KEY (`articleId`)
) ENGINE=InnoDB AUTO_INCREMENT=131 DEFAULT CHARSET=utf8;

/*Data for the table `article` */

insert  into `article`(`articleId`,`title`,`content`,`imgPath`,`otherPackagePath`,`saveTime`) values (114,'中心概况','<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">数字经济国际合作与创新发展中心，系由中国电子学会、</span><span style=\"line-height: 150%;\">重庆市科学技术协会、南岸区人民政府</span><span style=\"line-height: 150%;\">和重庆邮电大学四方联合建设，并挂靠重庆邮电大学的新型智库机构。旨在全面落实习近平总书记要求重庆“深度参与数字经济国际合作”的重要指示精神，发挥重庆“数字丝绸之路”内陆枢纽作用，推动重庆实施以大数据智能化为引领的创新驱动发展战略行动计划，辐射带动“一带一路”沿线数字产业化和产业数字化。</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">中心依托中国电子学会“数字经济百人会”，依靠</span><span style=\"line-height: 150%;\">重庆市科学技术协会</span><span style=\"line-height: 150%;\">“数字经济专家库”和南岸区“中国智谷科技园”，立足重庆邮电大学“大数据智能化实验场所、人才高地、科技高地”，致力于整合“一带一路”全球数字经济创新资源，培养输送数字经济创新创业国际化人才，开展数字经济资源国际精准对接；打造数字化转型创新公共服务平台，促成数字技术创新成果转化落地，推进快速形成经济高质量发展新动能。</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">中心面向数字经济发展需求，采用中国电子学会、</span><span style=\"line-height: 150%;\">重庆市科学技术协会、南岸区人民政府</span><span style=\"line-height: 150%;\">和重庆邮电大学四方联席会议指导下的主任负责制运行模式，积极开展数字经济研究、咨政与交流合作，为国家及地方数字经济发展建言、献策、出力。中心下设综合办公室、数字技术创新研究所、数字经济发展研究所、数字资源管理研究所、数字产权保护研究所、数字伦理规范研究所等业务机构，承担中心的具体业务职能。</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">中心办公地点设在重庆邮电大学经济管理学院楼，场地面积</span><span lang=\"EN-US\" style=\"line-height: 150%;\">500</span><span style=\"line-height: 150%;\">平方米；另在茶园新区建有协同创新基地</span><span lang=\"EN-US\" style=\"line-height: 150%;\">2000</span><span style=\"line-height: 150%;\">平方米。中心拥有各类科研设备价值</span><span lang=\"EN-US\" style=\"line-height: 150%;\">800</span><span style=\"line-height: 150%;\">余万元。拥有科研人员</span><span lang=\"EN-US\" style=\"line-height: 150%;\">68</span><span style=\"line-height: 150%;\">人，其中，省部级以上人才</span><span lang=\"EN-US\" style=\"line-height: 150%;\">11</span><span style=\"line-height: 150%;\">人；教授</span><span lang=\"EN-US\" style=\"line-height: 150%;\">30</span><span style=\"line-height: 150%;\">人，副教授</span><span lang=\"EN-US\" style=\"line-height: 150%;\">30</span><span style=\"line-height: 150%;\">人，讲师</span><span lang=\"EN-US\" style=\"line-height: 150%;\">8</span><span style=\"line-height: 150%;\">人；拥有博士学位</span><span lang=\"EN-US\" style=\"line-height: 150%;\">55</span><span style=\"line-height: 150%;\">人。近三年承担国家级科研项目</span><span lang=\"EN-US\" style=\"line-height: 150%;\">35</span><span style=\"line-height: 150%;\">项、省部级项目</span><span lang=\"EN-US\" style=\"line-height: 150%;\">70</span><span style=\"line-height: 150%;\">余项，到账科研经费</span><span lang=\"EN-US\" style=\"line-height: 150%;\">900</span><span style=\"line-height: 150%;\">余万元；发表科研论文</span><span lang=\"EN-US\" style=\"line-height: 150%;\">500</span><span style=\"line-height: 150%;\">余篇，出版学术著作</span><span lang=\"EN-US\" style=\"line-height: 150%;\">50</span><span style=\"line-height: 150%;\">余部，提交咨政报告</span><span lang=\"EN-US\" style=\"line-height: 150%;\">60</span><span style=\"line-height: 150%;\">余篇，获得省部级以上科研奖励</span><span lang=\"EN-US\" style=\"line-height: 150%;\">20</span><span style=\"line-height: 150%;\">余项。</span><span lang=\"EN-US\" style=\"font-size:12.0pt;line-height:150%\"><o:p></o:p></span></p>','-1','-1','2020-02-24 08:42:49'),(116,'组织章程','<p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><span style=\"text-indent: 0cm;\">图1 中心组织架构</span><br></span></p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第一章<span lang=\"EN-US\">&nbsp;&nbsp;&nbsp;&nbsp;</span>总则</b><span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第一条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">为规范组织行为，维护相关各方合法权益，遵照中华人民共和国法律法规，制订本章程。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二条</b><span lang=\"EN-US\">&nbsp;&nbsp;</span></span><span style=\"line-height: 24px;\">组织名称：数字经济国际合作与创新发展中心。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第三条</b><span lang=\"EN-US\">&nbsp;&nbsp;</span></span><span style=\"line-height: 24px;\">组织住所：重庆市南岸区南山街道崇文路<span lang=\"EN-US\">2</span>号重庆邮电大学经济管理学院楼。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第四条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">组织性质：非法人咨询机构。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第五条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">发起人：中国电子学会、重庆市科学技术协会、南岸区人民政府、重庆邮电大学。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第六条</b><span lang=\"EN-US\">&nbsp;</span></span><span style=\"line-height: 24px;\">法定代表人：中心主任。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第七条</b><span lang=\"EN-US\">&nbsp;&nbsp;</span></span><span style=\"line-height: 24px;\">本章程自生效之日起即具约束力。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二章<span lang=\"EN-US\">&nbsp;&nbsp;&nbsp;</span>业务范围</b><span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" align=\"left\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第八条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">主业范围：开展数字经济领域的交流合作、国际赛事、人才培养、成果转化、咨政服务。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第九条</b><span lang=\"EN-US\">&nbsp;&nbsp;</span></span><span style=\"line-height: 24px;\">业务变更：根据实际情况，经</span><span style=\"line-height: 24px;\">发起人协商一致，可以改变经营范围。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第三章<span lang=\"EN-US\">&nbsp;&nbsp;</span>组织架构</b><span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoBodyTextIndent2\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">中心采用发起人联席会议指导下的主任负责制。中心下设综合办公室、数字技术创新研究所、数字经济发展研究所、数字资源管理研究所、数字产权保护研究所、数字伦理规范研究所等业务机构，承担中心的具体业务职能。组织架构参见图<span lang=\"EN-US\">1。</span></span>&nbsp;</p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第四章<span lang=\"EN-US\">&nbsp;&nbsp;</span>四方联席会议</b><span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoBodyTextIndent2\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十一条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">四方联席会议由发起人中国电子学会、重庆市科学技术协会、南岸区人民政府、重庆邮电大学的分管领导构成，是中心的最高决策机构，决定中心重大事项，解决中心重大问题。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoBodyTextIndent2\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">联席会议召集人由四方分管领导共同担任，形成会商机制，原则上每半年会商对接一次。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoBodyTextIndent2\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十二条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">联席会议四方共同成立工作组，负责联系、沟通和落实具体合作内容，编制中心建设方案，并组织落地实施。具体工作由中国电子学会研究咨询中心、重庆市科学技术协会学会学术部、南岸区人民政府办公室、重庆邮电大学产学研合作办公室共同承担。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoBodyTextIndent2\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十三条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">中国电子学会要充分组织调动国内外数字经济创新资源，在重庆构建数字化转型服务平台，将数字经济研究咨询、科普培训和成果转化系列活动引入重庆，协同推动建立数字经济积聚区和国际合作平台等。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoBodyTextIndent2\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">重庆市科学技术协会要充分发挥优势，加强沟通协调，拓展合作平台，提升合作深度，在重点学术活动中给予相关支持。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoBodyTextIndent2\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">南岸区人民政府要积极支持中心的建设，为中心的运行提供必要的政策支持、经费支持，支持中心在南岸区开展活动。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoBodyTextIndent2\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">重庆邮电大学要落实相应学院或单位作为中心的具体挂靠。学校要为中心的运行落实必要的政策、经费和人员。要充分发挥专业人才培育优势，推动数字经济人才培养，积极组织参与数字经济交流活动。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第五章<span lang=\"EN-US\">&nbsp;&nbsp;</span>专家委员会</b><span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十四条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">中心设立专家委员会，向四方联席会议决策支持，为中心运行建言献策，并应邀参与中心的相关事务。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十五条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">专家委员会人选来源于四方联席会议推荐。其中，中国电子学会从“数字经济百人会”当中推荐；重庆市科协从“重庆科协专家库”当中推荐；南岸区政府从“中国智谷专家库”当中推荐；重庆邮电大学从“重邮数字技术经济专家库”当中推荐。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十六条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">专家委员会总人数设定为<span lang=\"EN-US\">20</span>人，联席会议四方可各推荐<span lang=\"EN-US\">5</span>人左右。任期不限，及时补缺。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第六章<span lang=\"EN-US\">&nbsp;&nbsp;</span>行政管理人员</b><span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十七条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">中心设置主任<span lang=\"EN-US\">1</span>人，副主任若干。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十八条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">中心主任由四方联席会议选定，全面负责中心的行政管理工作，并对四方联席会议负责。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十九条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">中心副主任由主任提名，报四方联席会议批准后赴任，分别分管主任委托的行政管理工作。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二十条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">中心根据需要，可在副主任当中确立<span lang=\"EN-US\">1</span>名常务副主任，负责中心的日常事务管理。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第七章<span lang=\"EN-US\">&nbsp;&nbsp;</span>下设机构</b><span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二十一条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">中心根据业务工作需要，可下设综合办公室和若干研究机构。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二十二条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">综合办公室主要负责中心的战略规划、国际合作、双创培训等事务，并承担中心的联络、文秘、人事、财务、后勤等服务职能。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二十三条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">中心下设研究机构初步定为数字技术创新研究所、数字经济发展研究所、数字资源管理研究所、数字产权保护研究所、数字伦理规范研究所。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">数字技术创新研究所主要开展数字通信技术、人工智能技术、传感网络技术、智能计算技术等方面的研究与咨询工作。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">数字经济发展研究所主要开展数字产业化、产业数字化等方面的研究与咨询工作。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">数字资源管理研究所主要开展数字资源共享、数字资源治理、数字资源安全等方面的研究与咨询工作。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">数字产权保护研究所主要开展数字确权、数字取证、数字溯源等方面的研究与咨询工作。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">数字伦理规范研究所主要开展人机冲突、隐私规范、数字滥用等方面的研究与咨询工作。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第八章<span lang=\"EN-US\">&nbsp;&nbsp;</span>中心资产</b><span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二十四条</b></span><span lang=\"EN-US\" style=\"line-height: 24px;\">&nbsp;&nbsp;</span><span style=\"line-height: 24px;\">中心由重庆邮电大学出资设立，现有资产主要包括办公场地<span lang=\"EN-US\">500</span>平方米、通信仪器设备<span lang=\"EN-US\">1</span>套、计算机<span lang=\"EN-US\">200</span>台、投影仪<span lang=\"EN-US\">20</span>台、扫描仪<span lang=\"EN-US\">10</span>台、复印机<span lang=\"EN-US\">5</span>台、打印机<span lang=\"EN-US\">30</span>台。资产合计人民币<span lang=\"EN-US\">849</span>万元。中心资产明细参见表<span lang=\"EN-US\">1</span>。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">表<span lang=\"EN-US\">1&nbsp;&nbsp;</span>中心资产明细<span lang=\"EN-US\"><o:p></o:p></span></span></p><div align=\"center\"><table class=\"MsoNormalTable\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\" style=\"width: 840.8px; border: none;\"><tbody><tr style=\"height: 1pt;\"><td width=\"25%\" valign=\"top\" style=\"height: 1pt; border: 1pt solid windowtext; width: 215.2px; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\">资产名称<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"29%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 248.8px; border-top: 1pt solid windowtext; border-right: 1pt solid windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\">资产数量<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"44%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 376px; border-top: 1pt solid windowtext; border-right: 1pt solid windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\">折合金额（万元）<span lang=\"EN-US\"><o:p></o:p></span></p></td></tr><tr style=\"height: 1pt;\"><td width=\"25%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 215.2px; border-right: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\">办公场地<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"29%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 248.8px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\"><span lang=\"EN-US\">500</span>平方米<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"44%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 376px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\"><span lang=\"EN-US\">400<o:p></o:p></span></p></td></tr><tr style=\"height: 1pt;\"><td width=\"25%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 215.2px; border-right: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\">通信仪器设备<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"29%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 248.8px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\"><span lang=\"EN-US\">1</span>套<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"44%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 376px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\"><span lang=\"EN-US\">300<o:p></o:p></span></p></td></tr><tr style=\"height: 1pt;\"><td width=\"25%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 215.2px; border-right: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\">计算机<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"29%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 248.8px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\"><span lang=\"EN-US\">200</span>台<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"44%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 376px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\"><span lang=\"EN-US\">100<o:p></o:p></span></p></td></tr><tr style=\"height: 1pt;\"><td width=\"25%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 215.2px; border-right: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\">投影仪<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"29%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 248.8px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\"><span lang=\"EN-US\">20</span>台<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"44%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 376px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\"><span lang=\"EN-US\">20<o:p></o:p></span></p></td></tr><tr style=\"height: 1pt;\"><td width=\"25%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 215.2px; border-right: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\">扫描仪<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"29%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 248.8px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\"><span lang=\"EN-US\">10</span>台<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"44%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 376px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\"><span lang=\"EN-US\">5<o:p></o:p></span></p></td></tr><tr style=\"height: 1pt;\"><td width=\"25%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 215.2px; border-right: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\">复印机<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"29%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 248.8px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\"><span lang=\"EN-US\">5</span>台<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"44%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 376px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\"><span lang=\"EN-US\">15<o:p></o:p></span></p></td></tr><tr style=\"height: 1pt;\"><td width=\"25%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 215.2px; border-right: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\">打印机<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"29%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 248.8px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\"><span lang=\"EN-US\">30</span>台<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"44%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 376px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\"><span lang=\"EN-US\">9<o:p></o:p></span></p></td></tr><tr style=\"height: 1pt;\"><td width=\"25%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 215.2px; border-right: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\">合计<span lang=\"EN-US\"><o:p></o:p></span></p></td><td width=\"29%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 248.8px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\"><span lang=\"EN-US\"><o:p>&nbsp;</o:p></span></p></td><td width=\"44%\" valign=\"top\" style=\"height: 1pt; border-bottom: 1pt solid windowtext; width: 376px; border-top: none; border-left: none; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;\"><p class=\"MsoNormal\" align=\"center\" style=\"margin-left: 4.5pt; text-indent: -4.5pt;\"><span lang=\"EN-US\">849<o:p></o:p></span></p></td></tr></tbody></table></div><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span lang=\"EN-US\" style=\"line-height: 24px;\"><o:p>&nbsp;</o:p></span></p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第九章 中心的解散和清算</b><span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二十五条</b><span lang=\"EN-US\">&nbsp;&nbsp;</span></span><span style=\"line-height: 24px;\">中心有下列情形之一的，可以解散：<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">（一）中心章程规定的营业期限届满；<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">（二）四方联席会议决议解散；<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">（三）因中心合并或者分立需要解散；<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">（四）依法被责令关闭或者被撤消；<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">（五）人民法院依法予以解散。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\">其中第（一）项情形可通过修改章程而存续。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二十六条</b><span lang=\"EN-US\">&nbsp;&nbsp;</span></span><span style=\"line-height: 24px;\">因第二十五条第（一）、（二）、（四）、（五）项的规定而解散的，应当依法组建清算组并进行清算；中心清算结束后，清算组制作清算报告，报四方联席会议确认，公告终止。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二十七条</b><span lang=\"EN-US\">&nbsp;&nbsp;</span></span><span style=\"line-height: 24px;\">清算组由四方联席会议组成，依照相关法律法规行使职权和承担义务。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" align=\"center\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第十章<span lang=\"EN-US\">&nbsp;&nbsp;</span>附则</b><span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二十八条</b><span lang=\"EN-US\"><b>&nbsp;</b>&nbsp;</span></span><span style=\"line-height: 24px;\">中心章程的解释权属四方联席会议。本章程如与国家法律法规相抵触的，以国家法律法规为准。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第二十九条</b>&nbsp;</span><span style=\"line-height: 24px;\">&nbsp;中心根据需要修改章程的，修改后章程应送四方联席会议备案。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\"><span style=\"line-height: 24px;\"><b>第三十条</b>&nbsp;</span><span style=\"line-height: 24px;\">&nbsp;本章程由四方联席会议审议通过后正式发布生效。</span></p>','/allFile/-180168816.png','-1','2020-02-24 08:49:51'),(118,'发展规划','<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\"><b>一、战略定位</b><span lang=\"EN-US\" style=\"\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">数字经济国际合作与创新发展中心，系由中国电子学会、重庆市科学技术协会、南岸区人民政府和重庆邮电大学四方联合建设，并挂靠重庆邮电大学的新型智库机构。旨在全面落实习近平总书记要求重庆“深度参与数字经济国际合作”的重要指示精神，发挥重庆“数字丝绸之路”内陆枢纽作用，推动重庆实施以大数据智能化为引领的创新驱动发展战略行动计划，辐射带动“一带一路”沿线数字产业化和产业数字化。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\"><b>二、发展目标</b><span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">联合中国数字经济百人会等权威智库、国内外知名数字经济研究机构、高等院校和领军企业，发挥重庆邮电大学“大数据智能化实验场所、人才高地、科技高地”作用，共同打造由知名专家学者及企业领袖等多元化高端人才组成的国际专家智库。聚焦数字经济发展战略、产业链创新路径、技术成果商用化、基地园区建设规划等关键需求，提供研究咨询、技术交流、人才培养、科普培训、投资运营等专业化、定制化智力支撑服务。五年建成国际知名的数字经济合作创新基地。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\"><b>三、重点任务</b><span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">1.</span><span style=\"line-height: 150%;\">打造数字化转型创新公共服务平台<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">打造线上线下一体化的公共服务平台体系，推动国际国内数字经济创新资源整合共享，吸引全球数字化转型服务商。以数字产业化、产业数字化为主线，围绕大数据、人工智能、工业互联网、区块链和高端软件等数字经济重点领域形成标准体系、解决方案和应用场景集合。全方位服务重庆市和中西部经济转型需求，提供面向全流程、全产业链、全生命周期的数字化创新转型方案，推动构建面向网络化生产制造的公共服务平台体系。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">2.</span><span style=\"line-height: 150%;\">促成具备条件的创新成果转化落地<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">面向重庆市发展壮大数字经济，加快数字化转型实际需求，发布对接数字经济重点领域创新成果需求及转化信息，引导部分兼具引领科技发展前沿和快速形成规模化产能特性的国际国内创新成果转化，促进数字经济产业培育、数字化改造提升、大数据智能化创新成果应用落地和试点示范，推动建立产业发展集聚区。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">3.</span><span style=\"line-height: 150%;\">开展数字经济资源国际精准对接活动<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">整合平台创新资源，构建面向“一带一路”和国际陆海贸易新通道沿线地区的数字经济可持续发展合作机制，组织国际国内政府部门、研究机构、重点企业围绕技术交流、产业转移、项目落地、人才培育和产融结合等方向开展国际化的数字经济精准对接活动，打造集发布前沿趋势、对接全球资源、交流先进经验、汇聚典型成果为一体的专业化、精品化、特色化平台。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">4.</span><span style=\"line-height: 150%;\">承办数字经济国际赛事活动<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">围绕“智能<span lang=\"EN-US\">+</span>数字化转型，全球创业创新大赛”为主题，邀请中国、澳大利亚、丹麦、德国、新加坡、英国等相关领域团队，在全球范围内组织数字经济国际赛事活动。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">5.</span><span style=\"line-height: 150%;\">组织数字经济学术活动<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">组织开展数字经济创新发展专题调查，召开数字经济学术研讨与交流会议，承办智博会数字经济分论坛，推介“数字丝绸之路”建设发展成果，宣传国家数字经济创新发展试验区建设成效。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">6.</span><span style=\"line-height: 150%;\">发布在线成果报告<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">实时在线发布数字经济工作论文、咨政报告、调研数据，定期出版数字经济皮书、学术专著、培训教材，精心制作数字经济视频、音频及<span lang=\"EN-US\">3D</span>展示成果。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\"><b>四、进度计划</b><span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">2020</span><span style=\"line-height: 150%;\">年度，建成重庆市重要的新型智库。重点围绕重庆市国家数字经济创新发展试验区建设工作，开展理论研究、方案起草、政策梳理、实施跟踪、专题调查、决策咨询等业务，协助地方党委政府建成建好国家数字经济创新发展试验区。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">2021-2022</span><span style=\"line-height: 150%;\">年度，建成国内知名的数字经济智库。重点围绕智博会的举办，组织国内一线专家开展数字经济学术论坛，研讨数字经济理论前沿问题，宣传国家数字经济创新发展试验区建设成效，推广数字经济创新发展经验，发布数字经济中文系列成果。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">2023-2024</span><span style=\"line-height: 150%;\">年度，建成国际知名的数字经济合作创新基地。围绕“智能<span lang=\"EN-US\">+</span>数字化转型”主题，承办数字经济全球创新创业赛事，推介“数字丝绸之路”建设发展成果，开展数字经济国际合作科研与国际学术交流，促进“一带一路”沿线国家和地区的数字化发展。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\"><b>五、保障措施</b><span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">1.</span><span style=\"line-height: 150%;\">实行四方联席会议机制，研究、决策合作中的重大事项，解决合作中的重大问题。联席会议主席由中国电子学会、重庆市科学技术协会、南岸区人民政府、重庆邮电大学主要领导共同担任，联席会议召集人由四方分管领导共同担任，形成会商机制，原则上每半年会商对接一次。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">2.</span><span style=\"line-height: 150%;\">成立四方联席会议秘书处，负责联系、沟通和落实具体合作内容，编制中心建设方案，并组织落地实施。具体工作由中国电子学会研究咨询中心、重庆市科学技术协会学会学术部、重庆市南岸区人民政府办公室、重庆邮电大学产学研合作办公室共同承担。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">3.</span><span style=\"line-height: 150%;\">实行四方联席会议指导下的主任负责制运行模式；设立综合办公室、数字技术创新研究所、数字经济发展研究所、数字资源管理研究所、数字产权保护研究所、数字伦理规范研究所等业务机构，承担中心的具体业务职能。<span lang=\"EN-US\"><o:p></o:p></span></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span lang=\"EN-US\" style=\"line-height: 150%;\">4.</span><span style=\"line-height: 150%;\">聘请专家委员会指导中心的重大决策和业务运行工作，协助中心开展高质量的国际合作、科学研究与咨政服务。<span lang=\"EN-US\"><o:p></o:p></span></span></p><p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">5.由重庆邮电大学为中心提供充足的办公场地和办公设备实施，在硬件建设上达到一流智库标准。</span></p>','-1','-1','2020-02-24 08:54:54'),(119,'四方联席会议','<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">第一届四方联席会议组成人员名单：</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">中国电子学会副秘书长</span><span lang=\"EN-US\" style=\"line-height: 150%;\">&nbsp; </span><span style=\"line-height: 150%;\">洪京一；</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">重庆市科学技术协会党组成员、副主席</span><span lang=\"EN-US\" style=\"line-height: 150%;\">&nbsp; </span><span style=\"line-height: 150%;\">程伟；</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">重庆市南岸区人民政府副区长</span><span lang=\"EN-US\" style=\"line-height: 150%;\">&nbsp; </span><span style=\"line-height: 150%;\">刘永华；</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">重庆邮电大学党委书记、校长</span><span lang=\"EN-US\" style=\"line-height: 150%;\">&nbsp; </span><span style=\"line-height: 150%;\">李林。</span><span lang=\"EN-US\" style=\"font-size:\n14.0pt;line-height:150%\"><o:p></o:p></span></p>','-1','-1','2020-02-24 08:56:06'),(120,'联席会议秘书处','<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">联系会议秘书处：</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">中国电子学会研究咨询中心主任</span><span lang=\"EN-US\" style=\"line-height: 150%;\">&nbsp; </span><span style=\"line-height: 150%;\">李颋；</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">重庆市科学技术协会学会学术部部长</span><span lang=\"EN-US\" style=\"line-height: 150%;\">&nbsp; </span><span style=\"line-height: 150%;\">段勇；</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">重庆市南岸区人民政府办公室主任</span><span lang=\"EN-US\" style=\"line-height: 150%;\">&nbsp; </span><span style=\"line-height: 150%;\">肖华云；</span><span lang=\"EN-US\" style=\"line-height: 150%;\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\"><span style=\"line-height: 150%;\">重庆邮电大学产学研合作办公室主任</span><span lang=\"EN-US\" style=\"line-height: 150%;\">&nbsp; </span><span style=\"line-height: 150%;\">温平川。</span><span lang=\"EN-US\" style=\"font-size:\n12.0pt;line-height:150%\"><o:p></o:p></span></p>','-1','-1','2020-02-24 08:57:00'),(122,'行政人员	','<p class=\"MsoNormal\" style=\"line-height: 25.2px;\">第一届行政管理人员：<span lang=\"EN-US\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\">中心主任：重庆邮电大学党委书记、校长<span lang=\"EN-US\">&nbsp;&nbsp;</span>李林（兼）<span lang=\"EN-US\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\">中心副主任：重庆邮电大学经济管理学院院长<span lang=\"EN-US\">&nbsp;&nbsp;</span>万晓榆（常务）<span lang=\"EN-US\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 重庆邮电大学社会科学处处长<span lang=\"EN-US\">&nbsp;&nbsp;</span>谢俊<span lang=\"EN-US\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"line-height: 25.2px;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 重庆邮电大学经济管理学院教授<span lang=\"EN-US\">&nbsp;&nbsp;</span>高锡荣</p>','-1','-1','2020-02-28 10:58:22'),(123,'业务部门','<p class=\"MsoNormal\" style=\"line-height: 150%;\">数字技术创新研究所<span lang=\"EN-US\">&nbsp;\n</span>雒江涛<span lang=\"EN-US\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\">数字经济发展研究所<span lang=\"EN-US\">&nbsp;\n</span>樊自甫<span lang=\"EN-US\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\">数字产权保护研究所<span lang=\"EN-US\">&nbsp;\n</span>黄东东<span lang=\"EN-US\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\">数字伦理规范研究所<span lang=\"EN-US\">&nbsp;\n</span>代金平<span lang=\"EN-US\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\">数字资源管理研究所<span lang=\"EN-US\">&nbsp;\n</span>王&nbsp; &nbsp;永<span lang=\"EN-US\"><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"line-height: 150%;\">综合办公室<span lang=\"EN-US\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span>卢华玲<span lang=\"EN-US\"><o:p></o:p></span></p>','-1','-1','2020-02-24 08:59:11'),(126,'中心主任-李林','李林（<span lang=\"EN-US\" style=\"\">1969—</span>），男，数字经济国际合作与创新发展中心主任。经济学博士，重庆邮电大学教授、硕士生导师。现任重庆邮电大学党委书记、校长。曾任重庆邮电学院院长助理；重庆邮电学院副院长、党委委员；重庆邮电大学副校长、党委委员；长江师范学院党委副书记、院长。长期从事经济管理、教育管理及相关领域研究工作。近年来，主持信息产业部通信软科学项目、重庆市科技计划软科学项目、重庆市教委科学技术计划软科学项目和重庆市教委教育教学改革研究重点项目（教育管理类）多项，主研多项重庆市科技计划软科学研究项目。在《经济体制改革》、《上海经济研究》、《山东社会科学》和《研究与发展管理》等多个核心期刊上公开发表学术论文<span lang=\"EN-US\" style=\"\">20</span>余篇，出版专著<span lang=\"EN-US\" style=\"\">1</span>部。<br>','/allFile/-1171218308.png','-1','2020-02-28 10:57:54'),(127,'中心常务副主任-万晓榆','万晓榆（<span lang=\"EN-US\" style=\"\">1963—</span>），男，数字经济国际合作与创新发展中心常务副主任。中共党员、工学博士。重庆邮电大学教授、博士生导师。重庆市巴渝学者，重庆市优秀教育工作者。现任重庆邮电大学经济管理学院院长<span lang=\"EN-US\" style=\"\">/</span>重庆邮电大学现代邮政学院院长，重庆市重点学科管理科学与工程学科负责人，重庆市电子商务与现代物流（高校）重点实验室主任，兼任中国信息消费推进联盟专家委员会委员、工业信息化部电信经济专家委员会委员，重庆市仲裁委员会专家、重庆市经济管理学会副会长，重庆市电子商务协会副理事长。研究方向：网络与信息经济理论，信息通信运营管理，消费者行为，通信网络技术。<br>','/allFile/1616757776.png','-1','2020-02-28 10:56:52'),(128,'中心副主任-谢俊','谢俊（<span lang=\"EN-US\" style=\"\">1980</span>－），女，数字经济国际合作与创新发展中心副主任。中共党员、教育学博士。重庆邮电大学教授、硕士生导师。重庆市学术技术带头人，重庆市首批青年骨干教师。现任重庆邮电大学社会科学处处长。主要研究方向：网络德育、网络伦理。近几年主持完成国家社会科学基金项目、教育部人文社会科学研究项目等国家级和省部级重大重点项目<span lang=\"EN-US\" style=\"\">10</span>余项，参与完成国家社会科学基金重大重点项目<span lang=\"EN-US\" style=\"\">6</span>项；出版学术专著<span lang=\"EN-US\" style=\"\">2</span>部，参编学术专著<span lang=\"EN-US\" style=\"\">4</span>部；发表学术论文近<span lang=\"EN-US\" style=\"\">40</span>篇，其中核心期刊<span lang=\"EN-US\" style=\"\">20</span>余篇，多篇论文被人大报刊复印资料、光明日报，中国教育报等刊载转载，获得重庆市社会科学优秀成果奖<span lang=\"EN-US\" style=\"\">4</span>项。','/allFile/265750143.png','-1','2020-02-28 10:55:11'),(129,'中心副主任-高锡荣','高锡荣（<span lang=\"EN-US\" style=\"\">1963</span>—），男，数字经济国际合作与创新发展中心副主任。<span class=\"fontstyle01\">中共党员、管理学</span>博士。<span class=\"fontstyle01\">重庆邮电大学</span>教授，硕士生导师。现任重庆市信息产业发展研究中心常务副主任、重庆邮电大学网络社会发展问题研究中心网络经济研究所所长。主要从事互联网创业、信息技术创新、数字经济、网络金融等方面的科学研究与人才培养工作。近年来承担国家重大软科学项目、国家社会科学基金项目、教育部人文社会科学项目等科研教研项目<span lang=\"EN-US\" style=\"\">50</span>余项。发表<span lang=\"EN-US\" style=\"\">CSSCI</span>期刊论文<span lang=\"EN-US\" style=\"\">70</span>余篇，<span lang=\"EN-US\" style=\"\">EI</span>检索论文<span lang=\"EN-US\" style=\"\">20</span>余篇，出版学术专著<span lang=\"EN-US\" style=\"\">9</span>部。科研成果获得重庆市社会科学优秀成果奖、重庆市发展研究奖、重庆市科技进步奖共<span lang=\"EN-US\" style=\"\">8</span>项。','/allFile/1680427132.png','-1','2020-02-28 10:54:23'),(130,'信息系统分析与设计','信息系统分析与设计是研究....内容。','-1','-1','2020-03-09 14:16:17');

